#!/usr/bin/env python3
"""Exactly evaluate two selected finite seeds before any mass optimization."""
import argparse,hashlib,importlib.util,json,os,sys,time
from fractions import Fraction as F
from pathlib import Path
sys.dont_write_bytecode=True
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def module(p,n):
 s=importlib.util.spec_from_file_location(n,p);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--archive',required=True);ap.add_argument('--out',required=True);a=ap.parse_args();root=Path(a.archive);start=time.monotonic();ep=root/'computation/round072/actual_halo_geometry.py';rp=root/'computation/round073/regional_credit_diagnostic_v2.py';engine=module(ep,'geometry');region=module(rp,'regional');seeds=[('single-diagonal',[(['-12/25','-12/25'],'16/25')]),('cross-pair',[(['-12/25','6/25'],'8/25'),(['6/25','-12/25'],'8/25')])];results=[]
 for name,external in seeds:
  data={'threshold':'1','background':'Lebesgue R2','geometry':'centered axis-parallel common-radius squares','S_indices':list(range(25)),'positions':[[str(F(6*i,25)),str(F(6*j,25))] for i in range(5) for j in range(5)]+[p for p,m in external],'masses':['1/25']*25+[m for p,m in external]};ip=Path('computation/inputs/r074/pilot')/(name+'.json');ip.write_text(json.dumps(data,indent=2)+'\n');g=engine.evaluate(data,bits=72);assert g['maximum_mass']=='1' and g['chosen_S_is_maximum'];base=g['base_scale'];assert all(r['mass_units_base_squared']<=max(base*base,r['span_squared_units_base_squared']) for r in g['full_closure_catalog']);D=g['coordinate_scale'];box=[]
  for x in [F(-1,2),F(-1,25),F(-1,2),F(-1,25)]:assert (x*D).denominator==1;box.append(int(x*D))
  job=next(j for j in g['all_maximum_block_evaluations'] if j['chosen_S']);fi=[r['inner'] for r in g['full_directed_rectangles']];fo=[r['outer'] for r in g['full_directed_rectangles']];ri=[r['inner'] for r in job['residual_directed_rectangles']];ro=[r['outer'] for r in job['residual_directed_rectangles']];lf,hr,ld=region.sweep(region.clip(fi,box),region.clip(ro,box));hf,lr,hd=region.sweep(region.clip(fo,box),region.clip(ri,box));enc=lambda lo,hi:engine.enc(lo,hi,D*D);d=enc(ld,hd);aux=F(2,25);target=F(631,5000)
  state={k:g[k] for k in ['positive_source_count','maximum_mass','maximum_count','full_closure_count','full_eligible_closure_count','eligible_component_count','actual_total_mass','actual_span','nonterminal_gap_span_squared_minus_35total_over33','nonterminal']};results.append({'name':name,'input_path':str(ip),'input_sha256':sha(ip),'state':state,'all_complete_maxblock_caps_exact_checked':len(g['full_closure_catalog']),'SW_corner_full_halo':enc(lf,hf),'SW_corner_residual_halo':enc(lr,hr),'SW_corner_actual_deletion':d,'full_global_halo':g['full_halo'],'chosen_S_global_Delta':job['actual_Delta'],'auxiliary_threshold':'2/25','main_threshold':'631/5000','auxiliary_margin_lower':str(F(d['lower'])-aux),'main_margin_lower':str(F(d['lower'])-target),'strict_auxiliary_violation':F(d['lower'])>aux,'strict_main_violation':F(d['lower'])>target,'scope':'One exactly specified finite input; complete full/residual halo enclosures clipped to closedSW corner. AllS retained for caps; all outside sources are strictly inP_SW.'})
 out={'schema':'r074-two-selected-single-corner-seeds-v1','python':sys.version,'pid':os.getpid(),'source_sha256':sha(Path(__file__)),'frozen_geometry_source_path':str(ep),'frozen_geometry_source_sha256':sha(ep),'frozen_clipped_area_source_path':str(rp),'frozen_clipped_area_source_sha256':sha(rp),'parameters':{'n':5,'SW_corner':['-1/2','-1/25','-1/2','-1/25'],'P_SW_open':['-1','23/50','-1','23/50'],'bits':72,'seed':None,'outside_position_search':False,'mass_optimization':False},'results':results,'seconds':time.monotonic()-start,'scope':'Two explicit model-selection seeds authorized withAstra; no blind position search and no extension to n9. Floats display exact enclosures only.'};Path(a.out).write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'pid':os.getpid(),'seconds':out['seconds'],'results':[{'name':r['name'],'SW_Delta':r['SW_corner_actual_deletion'],'auxiliary_violation':r['strict_auxiliary_violation'],'main_violation':r['strict_main_violation']} for r in results]},indent=2))
if __name__=='__main__':main()
